def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = remaining / (bins + 1e-8)
    return np.where(remaining >= 0, np.cos(2 * np.pi * ratio), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
