def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = remaining / (bins + 1e-8)
    return np.where(remaining >= 0, np.exp(-(ratio - 0.1)**2 / 0.05), -np.inf)
